from typing import List, Tuple

def process_queries(Q: int, queries: List[Tuple[int, int]]) -> List[int]:
    A = []
    results = []

    for query in queries:
        if query[0] == 1:
            A.append(query[1])
        elif query[0] == 2:
            index = len(A) - query[1]
            results.append(A[index])

    return results
